// 姓名詳批：五格、三才、三運的傳統解說，以及名字和八字喜用的配合。
//
// nameReading(analyseName(full, analysis), analysis) returns plain data for the page. The levels are this project's
// own (src/core/name.js: 康熙筆畫, two 81-number tables, 半吉 where they differ, the 三才 table); the traditional texts
// come from src/core/name-texts.js (generated by scripts/make-name-texts.mjs). Nothing here changes the simulation:
// the name's small tilt is effects in name.js.
import { SHULI_TEXTS, SANCAI_TEXTS, YUNSHI } from "./name-texts.js";
import { fiveGrids, shuli, LEVEL_NAME, numberElement } from "./name.js";
import { elementRoles } from "./detail.js";
import { ELEMENTS } from "./analysis.js";

const GRIDS = ["天格", "人格", "地格", "外格", "總格"];
// The scored grids and their weights within 五格數理. 天格 comes with the surname and is not scored.
const SCORED = { 人格: 0.4, 總格: 0.25, 地格: 0.2, 外格: 0.15 };
const GENERATES = { 木: "火", 火: "土", 土: "金", 金: "水", 水: "木" };
const CONTROLS = { 木: "土", 土: "水", 水: "火", 火: "金", 金: "木" };
const wrap = n => ((n - 1) % 80) + 1;   // as in shuli(): past 81 the numbers start over
const quote = chars => [...new Set(chars)].map(ch => `「${ch}」`).join("");
const lines = chars => chars.filter((c, i) => chars.findIndex(x => x.ch === c.ch) === i).map(c => c.text).join("");   // a repeated character once

export const SCORE_LABEL = "傳統姓名學評分（僅供參考）";
const VERDICTS = [[90, "整體配置很好"], [82, "整體配置不錯"], [74, "整體中上"], [66, "整體普通，有幾處不理想"], [0, "傳統上評價不高"]];
const CALM = {
  grid: "傳統上這是凶數，但名字只是命理裡很小的一環，要和八字、大運合起來看，在這個模擬裡也不影響壽命和重病；這是遊戲，不需要為此改名。",
  sancai: "三才只看三個格的五行生剋，是很粗略的判斷，影響有限。",
  fortune: "這是依五行生剋推出的傳統說法，僅供參考。",
};
const NOTES = [
  "姓名學的流派很多，筆畫算法和 81 數理表都有不同版本。這裡用康熙筆畫；兩種數理表說法不同的數，算半吉。",
  "五格、三才、三運的解說都是傳統說法，僅供參考。名字在這個模擬裡的影響很小，每個領域最多 ±5%，而且不影響壽命和重病。",
];
const CREDIT = "81 數理、三才、三運的解說文字取自 shunshi-naming-core（MIT 授權，Copyright (c) 2026 Shunshi.AI），轉成臺灣用字。";
const FORTUNES = [
  ["成功運", "天格", "人格與天格的關係，看上進與事業能否順利，以及長輩、上司與時勢的助力。"],
  ["基礎運", "地格", "人格與地格的關係，看根基穩不穩：家庭、住所、身體，以及部屬和晚輩的助力。"],
  ["社交運", "外格", "人格與外格的關係，看人際是否融洽，以及外在環境和別人怎麼對待你。"],
];

// How element a (of grid an) stands to element b (of grid bn), in the usual words.
function relation(an, a, bn, b) {
  if (a === b) return `${an}與${bn}同屬${a}，比和`;
  if (GENERATES[a] === b) return `${an}（${a}）生${bn}（${b}）`;
  if (GENERATES[b] === a) return `${bn}（${b}）生${an}（${a}）`;
  if (CONTROLS[a] === b) return `${an}（${a}）剋${bn}（${b}）`;
  return `${bn}（${b}）剋${an}（${a}）`;
}

// How each grid is added up, from the primary stroke counts (the same formulas as fiveGrids in name.js).
function formulas(n, s, g) {
  const t = c => `${c.ch} ${c.strokes.primary}`, ONE = "1（假一）";
  const all = [...s, ...g], sum = all.reduce((a, c) => a + c.strokes.primary, 0);
  const f = {
    天格: s.length > 1 ? `${t(s[0])} + ${t(s[1])}` : `${t(s[0])} + ${ONE}`,
    人格: `${t(s[s.length - 1])} + ${t(g[0])}`,
    地格: g.length > 1 ? g.map(t).join(" + ") : `${t(g[0])} + ${ONE}`,
    外格: `${s.length > 1 ? t(s[0]) : ONE} + ${g.length > 1 ? t(g[g.length - 1]) : ONE}`,
    總格: all.map(t).join(" + ") + (sum > 81 ? ` = ${sum}，超過 81 減 80` : ""),
  };
  return Object.fromEntries(GRIDS.map(k => [k, `${f[k]} = ${n.grids[k].value}`]));
}

// The other values each grid takes under the other stroke readings of disputed characters (at most 16 readings, as
// in name.js).
function alternatives(n, surnameLength) {
  let combos = [[]];
  for (const c of n.chars) combos = combos.flatMap(p => c.strokes.all.map(x => [...p, x])).slice(0, 16);
  const out = Object.fromEntries(GRIDS.map(k => [k, new Set()]));
  for (const list of combos) {
    const v = fiveGrids(list.slice(0, surnameLength), list.slice(surnameLength));
    for (const k of GRIDS) if (v[k] !== n.grids[k].value) out[k].add(v[k]);
  }
  return Object.fromEntries(GRIDS.map(k => [k, [...out[k]].sort((a, b) => a - b)]));
}

// Whether the grid's level changes between stroke readings.
const levelVaries = g => (g.good > 0 && g.good < g.readings) || g.mean !== g.level;

function gridReading(key, g, formula, alts) {
  const judged = key in SCORED, t = SHULI_TEXTS[wrap(g.value)], notes = [];
  if (!judged) notes.push("天格由姓氏決定，是祖先傳下來的，多數流派不論吉凶，這裡不計分，只介紹這個數的傳統說法。");
  if (judged && !g.agree) notes.push(`兩種數理表說法不同（一說${g.tables[0]}、一說${g.tables[1]}），這裡算半吉。`);
  // The source marks 1 as impossible in a real name: 人格 and 外格 are at least 2 (1 + 1).
  if ((key === "人格" || key === "外格") && g.value < 2) notes.push("人格和外格最小是 2，不會是這個數，請檢查筆畫。");
  if (alts.length) {
    const values = alts.map(v => (judged ? `${v}（${LEVEL_NAME[shuli(v).level]}）` : String(v))).join("、");
    notes.push(`依筆畫有爭議的字的其他算法，這一格也可能是 ${values}${judged && levelVaries(g) ? `；${g.readings} 種算法裡有 ${g.good} 種是吉` : ""}。`);
  }
  if (judged && g.level < 0) notes.push(CALM.grid);
  return {
    key, value: g.value, element: g.element, level: judged ? LEVEL_NAME[g.level] : "不論吉凶", judged, role: g.role, formula,
    poem: t.poem, keywords: t.keywords, text: t.text, note: notes.join(""),
  };
}

// 名字與八字: each given-name character's 字形五行 (from its radical, when it reads plainly) and 數理五行 (from its
// strokes) against the chart. The elements are named as in detail.js: 用神 and 喜神 (the chart's `useful`) help, 忌神
// and 仇神 (`avoid`) go against it, 閒神 neither. The surname is left out: it comes with the family.
const SIGN = { 用神: 1, 喜神: 1, 閒神: 0, 仇神: -1, 忌神: -1 };
function elementsReading(given, analysis) {
  const roles = analysis ? elementRoles(analysis) : null;
  const word = e => `${e}${roles[e] === "閒神" ? "是閒神，不喜不忌" : `是${roles[e]}`}`;
  const chars = given.map(c => {
    const alt = [...new Set(c.strokes.all.slice(1).filter(x => numberElement(x) !== c.number).map(x => `${x} 畫屬${numberElement(x)}`))];
    const strokes = `${c.strokes.primary} 畫屬${c.number}${alt.length ? `（另一種算法 ${alt.join("、")}）` : ""}`;
    const head = c.form ? `「${c.ch}」字形屬${c.form}，數理 ${strokes}` : `「${c.ch}」字形五行不明確，只看數理：${strokes}`;
    const out = { ch: c.ch, form: c.form || "", number: c.number, strokes: c.strokes.all, formRole: "", numberRole: "", verdict: "", text: `${head}。`, value: 0, mixed: false };
    if (!roles) return out;
    const own = c.form && c.form !== c.number ? [c.form, c.number] : [c.number];
    out.value = own.reduce((sum, e) => sum + SIGN[roles[e]], 0) / own.length;
    out.mixed = own.some(e => SIGN[roles[e]] > 0) && own.some(e => SIGN[roles[e]] < 0);
    out.formRole = c.form ? roles[c.form] : "";
    out.numberRole = roles[c.number];
    out.verdict = out.value === 1 ? "對八字有幫助" : out.value > 0 ? "對八字有些幫助" : out.value === -1 ? "和八字不合" : out.value < 0 ? "和八字略有不合" : out.mixed ? "一喜一忌，作用互相抵消" : "對八字的影響不大";
    const judged = !c.form ? word(c.number) : c.form === c.number ? `兩者都屬${c.number}，${word(c.number).slice(1)}` : `${word(c.form)}，${word(c.number)}`;
    out.text = `${head}${c.form ? "：" : "，"}${judged}，${out.verdict}。`;
    return out;
  });

  const about = "姓氏是祖先傳下來的，不列入比較。字形五行看部首，數理五行看筆畫的尾數（1、2 木，3、4 火，5、6 土，7、8 金，9、0 水）。用神、喜神對命盤有利，忌神、仇神不利，閒神影響不大。";
  const strip = ({ value, mixed, ...rest }) => rest;
  if (!roles) return { chars: chars.map(strip), useful: [], avoid: [], roles: {}, about, text: `沒有命盤資料，只列出名字的五行，沒有和喜用神比較。${lines(chars)}`, short: "", balance: null };

  const order = [...new Set([...analysis.useful, ...analysis.avoid, ...ELEMENTS])];
  const named = r => order.filter(e => roles[e] === r).join("、");
  const dm = analysis.dayMaster;
  const intro = `八字日主是${dm.stem}${dm.element}，${analysis.strength}。` +
    `${named("用神") ? `用神${named("用神")}${named("喜神") ? `，喜神${named("喜神")}` : ""}` : "喜用神不明顯"}；` +
    `${named("忌神") ? `忌神${named("忌神")}${named("仇神") ? `，仇神${named("仇神")}` : ""}` : "沒有明顯的忌神"}` +
    `${named("閒神") ? `；${named("閒神")}是閒神` : ""}。`;
  const helps = chars.filter(c => c.value > 0).map(c => c.ch), hurts = chars.filter(c => c.value < 0).map(c => c.ch);
  const mixed = chars.filter(c => c.value === 0 && c.mixed).map(c => c.ch);
  const balance = chars.reduce((sum, c) => sum + c.value, 0) / chars.length;
  // The roles the helping and the hurting characters touch, e.g. 用神 or 仇神.
  const touched = (list, sign) => ["用神", "喜神", "忌神", "仇神"].filter(r => Math.sign(SIGN[r]) === sign && chars.some(c => list.includes(c.ch) && (c.numberRole === r || c.formRole === r))).join("、");
  const good = touched(helps, 1), bad = touched(hurts, -1);
  let end, short;
  if (helps.length && !hurts.length) {
    end = `${quote(helps)}補到${good}，傳統上叫做「補八字」，被認為能補足命局所缺，是名字加分的地方。`;
    short = `名字的五行補到${good}`;
  } else if (hurts.length && !helps.length) {
    end = `${quote(hurts)}落在${bad}上，傳統上認為會加重命局的偏頗；不過名字只是很小的一個因素，影響有限。`;
    short = `名字的五行落在${bad}上`;
  } else if (helps.length) {
    end = `${quote(helps)}補到${good}，${quote(hurts)}落在${bad}上，一好一壞，${balance > 0 ? "整體還是偏向有利" : balance < 0 ? "整體略偏不利" : "整體打平"}。`;
    short = "名字的五行有喜有忌";
  } else if (mixed.length) {
    end = `${quote(mixed)}一喜一忌，作用互相抵消，整體對八字不加分也不扣分。`;
    short = "名字的五行喜忌互相抵消";
  } else {
    end = "名字的五行都是閒神，不喜不忌，對八字不加分也不扣分。";
    short = "名字的五行不喜不忌";
  }
  return { chars: chars.map(strip), useful: [...analysis.useful], avoid: [...analysis.avoid], roles, about, text: intro + lines(chars) + end, short, balance };
}

// 傳統姓名學評分（僅供參考）, 0–100. Every part is on the same scale, a level from −1 to +1 giving 75 + 25 × level
// points, so each part scores 50 to 100:
//   五格數理 60 %: 人格 0.40, 總格 0.25, 地格 0.20, 外格 0.15, each at its level in name.js (吉 +1, 半吉 0, 凶 −1),
//                  averaged over the stroke readings when a character is disputed. 天格 is not scored.
//   三才 20 %:     its level (大吉 +2 … 大凶 −2) halved.
//   八字喜用 20 %: the given name's balance: the mean over its characters of the mean over each character's known
//                  elements (字形 when known, 數理) of +1 用神 or 喜神, 0 閒神, −1 忌神 or 仇神. Without a chart this
//                  part is left out and the other two count 75 % and 25 %.
// A name that is 吉 everywhere and fits the chart scores 100; one that is 凶 everywhere and goes against it, 50.
function scoreOf(n, balance) {
  const points = level => 75 + 25 * level;
  const parts = [
    ["五格數理", Object.entries(SCORED).reduce((s, [k, w]) => s + w * points(n.grids[k].mean), 0), 0.6],
    ["三才", points(n.sancai.level / 2), 0.2],
  ];
  if (balance !== null) parts.push(["八字喜用", points(balance), 0.2]);
  const total = parts.reduce((s, [, , w]) => s + w, 0);
  const value = Math.round(parts.reduce((s, [, p, w]) => s + p * w, 0) / total);
  const note = balance !== null
    ? "五格數理占 60%（人格 40%、總格 25%、地格 20%、外格 15%），三才占 20%，名字和八字喜用神的配合占 20%；每一項都換算成 50 到 100 分。"
    : "五格數理占 75%（人格 40%、總格 25%、地格 20%、外格 15%），三才占 25%；沒有命盤資料，不計八字喜用神。每一項都換算成 50 到 100 分。";
  return { value: Math.max(0, Math.min(100, value)), note, parts: parts.map(([part, p, w]) => ({ part, points: Math.round(p), weight: Math.round(w / total * 100) })) };
}

function disputedReading(n, disputedChars) {
  if (!disputedChars.length) return "";
  const list = disputedChars.map(c => `「${c.ch}」有 ${c.strokes.all.join("、")} 畫${c.strokes.all.length === 2 ? "兩" : c.strokes.all.length === 3 ? "三" : "幾"}種算法`).join("，");
  const used = disputedChars.map(c => `「${c.ch}」${c.strokes.primary} 畫`).join("、");
  const readings = n.grids.總格.readings;
  const changed = Object.keys(SCORED).filter(k => levelVaries(n.grids[k])).map(k => `${k}在 ${readings} 種算法裡有 ${n.grids[k].good} 種是吉`);
  return `${list}。五格以${used}為準，其他 ${readings - 1} 種算法也都算過：${changed.length ? `${changed.join("，")}，其他各格的吉凶不變` : "各格的吉凶都不受影響"}。`;
}

// The reading, or { error } when the name could not be analysed:
//   { full, surname, given, summary, score, scoreLabel, scoreNote, scoreParts: [{ part, points, weight }], strokes,
//     grids: [{ key, value, element, level, judged, role, formula, poem, keywords, text, note }]   天格 人格 地格 外格 總格
//     sancai: { elements, level, about, relation, text, note },
//     yunshi: { 成功運, 基礎運, 社交運: { from: "人格", to, elements, relation, level, about, text, note } },
//     elements: { chars: [{ ch, form, number, strokes, formRole, numberRole, verdict, text }], useful, avoid, roles,
//                 about, text },
//     disputed, notes, credit }
// Grid levels are 吉, 半吉 or 凶 (天格: 不論吉凶); 三才 and 運 levels 大吉 … 大凶. No field is null: an empty string
// means there is nothing to say (form "" is a character without a clear 字形五行).
export function nameReading(n, analysis = null) {
  if (!n || n.error) return { error: (n && n.error) || "沒有辦法分析這個名字。" };
  const surnameLength = [...n.surname].length;
  const s = n.chars.slice(0, surnameLength), given = n.chars.slice(surnameLength);
  const f = formulas(n, s, given), alts = alternatives(n, surnameLength);
  const grids = GRIDS.map(k => gridReading(k, n.grids[k], f[k], alts[k]));

  const [tian, ren, di] = [...n.sancai.elements];
  const sancai = {
    elements: n.sancai.elements, level: n.sancai.name,
    about: "三才是天格、人格、地格的五行配置，傳統上用來看成功、根基與身心是否安穩。",
    relation: `天格屬${tian}、人格屬${ren}、地格屬${di}：${relation("天格", tian, "人格", ren)}，${relation("人格", ren, "地格", di)}。`,
    text: SANCAI_TEXTS[n.sancai.elements],
    note: n.sancai.level < 0 ? CALM.sancai : "",
  };

  const yunshi = {};
  for (const [name, other, about] of FORTUNES) {
    const a = n.grids.人格.element, b = n.grids[other].element, e = YUNSHI[name][a + b];
    yunshi[name] = { from: "人格", to: other, elements: a + b, relation: `${relation("人格", a, other, b)}。`, level: e.level, about, text: e.text, note: e.level.includes("凶") ? CALM.fortune : "" };
  }

  const el = elementsReading(given, analysis);
  const score = scoreOf(n, el.balance);
  const disputedChars = n.chars.filter(c => c.strokes.all.length > 1);

  const scored = grids.filter(g => g.judged), count = l => scored.filter(g => g.level === l).length;
  const [good, half, bad] = ["吉", "半吉", "凶"].map(count);
  const renLevel = grids[1].level;
  const gridPart = good === 4 ? "人格、地格、外格、總格四格都是吉數"
    : bad === 4 ? "人格、地格、外格、總格四格都是凶數"
    : `計分的四格裡有 ${[good && `${good} 格吉`, half && `${half} 格半吉`, bad && `${bad} 格凶`].filter(Boolean).join("、")}，主運人格${renLevel === "吉" ? "是吉數" : renLevel === "凶" ? "是凶數" : "算半吉"}`;
  // The verdict follows the score (over the random names of the simulation its median is 83, its 10th percentile 69
  // and its 90th 94), except that a 凶 主運 caps it: traditionally 人格 weighs more than the rest together.
  let at = VERDICTS.findIndex(([min]) => score.value >= min);
  if (renLevel === "凶") at = Math.max(at, 3);
  const overall = VERDICTS[at][1];
  let summary = `「${n.full}」${overall}：${gridPart}，三才「${sancai.elements}」${sancai.level}${el.short ? `；${el.short}` : ""}。`;
  if (score.value < 66) summary += "不過名字只是很小的一個因素，這是模擬遊戲，不需要為此改名。";

  return {
    full: n.full, surname: n.surname, given: n.given,
    summary,
    score: score.value, scoreLabel: SCORE_LABEL, scoreNote: score.note, scoreParts: score.parts,
    strokes: n.chars.map(c => `${c.ch} ${c.strokes.all.join(" 或 ")}`).join("、"),
    grids, sancai, yunshi,
    elements: { chars: el.chars, useful: el.useful, avoid: el.avoid, roles: el.roles, about: el.about, text: el.text },
    disputed: disputedReading(n, disputedChars),
    notes: [...NOTES],
    credit: CREDIT,
  };
}
